49	 */
50	
51	@RestController
52	@CrossOrigin(exposedHeaders = "errors, content-type")
53	@RequestMapping("/api")
54	public class OwnerRestControllerV1 implements OwnersApi {
55	
56	    private final ClinicService clinicService;
57	
58	    private final OwnerMapper ownerMapper;
59	
60	    private final PetMapper petMapper;
61	
62	    private final VisitMapper visitMapper;
63	
64	    public OwnerRestControllerV1(ClinicService clinicService,
65	                                 OwnerMapper ownerMapper,
66	                                 PetMapper petMapper,
67	                                 VisitMapper visitMapper) {
68	        this.clinicService = clinicService;
69	        this.ownerMapper = ownerMapper;
70	        this.petMapper = petMapper;
71	        this.visitMapper = visitMapper;
72	    }
73	
74	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
75	    @Override
76	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
77	        Collection<Owner> owners;
78	        if (lastName != null) {
79	            owners = this.clinicService.findOwnerByLastName(lastName);
80	        } else {
81	            owners = this.clinicService.findAllOwners();
82	        }
83	        if (owners.isEmpty()) {
84	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
85	        }
86	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
87	    }
88	
89	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
90	    @Override
91	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
92	        Owner owner = this.clinicService.findOwnerById(ownerId);
93	        if (owner == null) {
94	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
95	        }
96	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
97	    }
98	
99	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
100	    @Override
101	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
102	        HttpHeaders headers = new HttpHeaders();
103	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
104	        Collection<Owner> existingOwners = this.clinicService.findAllOwners().stream()
105	            .filter(o -> !o.isDeleted()).toList();
106	        if (DailyRegistrationLimit.isReached(existingOwners)) {
107	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
108	        }
109	        HouseholdDuplicates.assignHousehold(owner, existingOwners, ownerFieldsDto.getSharesHousehold());
110	        if (IdentityKey.isDuplicate(owner, existingOwners)
111	            || CityCapacity.isAtCapacity(owner, existingOwners)) {
112	            return new ResponseEntity<>(HttpStatus.CONFLICT);
113	        }
114	        owner.setPossibleDuplicateOf(
115	            PossibleDuplicates.matchId(owner, existingOwners, ownerFieldsDto.getSharesHousehold()));
116	        owner.setNamesakeCount(Namesakes.count(owner, existingOwners));
117	        owner.setMemberId(CustomerCodes.build(owner, existingOwners));
118	        owner.setMembershipCap(MembershipCap.of(owner, existingOwners));
119	        owner.setCapacityWarning(CityCapacityWarning.isApproaching(owner, existingOwners));
120	        this.clinicService.saveOwner(owner);
121	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
122	        ownerDto.setBulkSignupWarning(BulkSignupWarning.isTriggered(existingOwners));
123	        headers.setLocation(UriComponentsBuilder.newInstance()
124	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
125	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
126	    }
127	
128	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
129	    @Override
130	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
131	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
132	        if (currentOwner == null) {
133	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
134	        }
135	        currentOwner.setAddress(ownerFieldsDto.getAddress());
136	        currentOwner.setCity(ownerFieldsDto.getCity());
137	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
138	        currentOwner.setLastName(ownerFieldsDto.getLastName());
139	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
140	        this.clinicService.saveOwner(currentOwner);
141	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
142	    }
143	
144	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
145	    @Transactional
146	    @Override
147	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
148	        Owner owner = this.clinicService.findOwnerById(ownerId);
149	        if (owner == null) {
150	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
151	        }
152	        owner.setDeleted(true);
153	        this.clinicService.saveOwner(owner);
154	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
155	    }
156	
157	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
158	    @Override
159	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
160	        Owner owner = this.clinicService.findOwnerById(ownerId);
161	        if (owner == null) {
162	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
163	        }
164	        HttpHeaders headers = new HttpHeaders();
165	        Pet pet = petMapper.toPet(petFieldsDto);
166	        owner.setId(ownerId);
167	        pet.setOwner(owner);
168	        pet.getType().setName(null);
169	        this.clinicService.savePet(pet);
170	        PetDto petDto = petMapper.toPetDto(pet);
171	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
172	            .buildAndExpand(pet.getId()).toUri());
173	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
174	    }
175	
176	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
177	    @Override
178	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
179	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
180	        if (currentOwner != null) {
181	            Pet currentPet = this.clinicService.findPetById(petId);
182	            if (currentPet != null) {
183	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
184	                currentPet.setName(petFieldsDto.getName());
185	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
186	                this.clinicService.savePet(currentPet);
187	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
188	            }
189	        }
190	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
191	    }
192	
193	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
194	    @Override
195	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
196	        HttpHeaders headers = new HttpHeaders();
197	        Visit visit = visitMapper.toVisit(visitFieldsDto);
198	        Pet pet = new Pet();
199	        pet.setId(petId);
200	        visit.setPet(pet);
201	        this.clinicService.saveVisit(visit);
202	        VisitDto visitDto = visitMapper.toVisitDto(visit);
203	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
204	            .buildAndExpand(visit.getId()).toUri());
205	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
206	    }
207	
208	
209	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
210	    @Override
211	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
212	        Owner owner = this.clinicService.findOwnerById(ownerId);
213	        if (owner != null) {
214	            Pet pet = owner.getPet(petId);
215	            if (pet != null) {
216	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
217	            }
218	        }
219	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
220	    }
221	}
