27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	@EntityListeners(OwnerAuditListener.class)
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
50	    private String telephone;
51	
52	    @Column(name = "title")
53	    private String title;
54	
55	    public String getTitle() {
56	        return this.title;
57	    }
58	
59	    public void setTitle(String title) {
60	        this.title = title;
61	    }
62	
63	    @Column(name = "email")
64	    private String email;
65	
66	    @Column(name = "postcode")
67	    private String postcode;
68	
69	    public String getPostcode() {
70	        return this.postcode;
71	    }
72	
73	    public void setPostcode(String postcode) {
74	        this.postcode = postcode;
75	    }
76	
77	    @Column(name = "registration_date")
78	    private LocalDate registrationDate;
79	
80	    @Column(name = "member_id")
81	    private String memberId;
82	
83	    @Column(name = "household_id")
84	    private String householdId;
85	
86	    @org.hibernate.annotations.Formula(
87	        "(select cast(count(*) as integer) from owners hm where hm.household_id = household_id)")
88	    private Integer householdSize;
89	
90	    public Integer getHouseholdSize() {
91	        return this.householdSize;
92	    }
93	
94	    public void setHouseholdSize(Integer householdSize) {
95	        this.householdSize = householdSize;
96	    }
97	
98	    @Column(name = "namesake_count")
99	    private Integer namesakeCount;
100	
101	    public Integer getNamesakeCount() { return this.namesakeCount; }
102	
103	    public void setNamesakeCount(Integer namesakeCount) { this.namesakeCount = namesakeCount; }
104	
105	    @Column(name = "membership_cap")
106	    private Integer membershipCap;
107	
108	    public Integer getMembershipCap() { return this.membershipCap; }
