128	    @Column(name = "deleted")
129	    private boolean deleted;
130	
131	    public boolean isDeleted() { return this.deleted; }
132	
133	    public void setDeleted(boolean deleted) { this.deleted = deleted; }
134	
135	    @Column(name = "birth_date")
136	    private LocalDate birthDate;
137	
138	    public LocalDate getBirthDate() { return this.birthDate; }
139	
140	    public void setBirthDate(LocalDate birthDate) { this.birthDate = birthDate; }
141	
142	    public String getMemberId() {
143	        return this.memberId;
144	    }
145	
146	    public void setMemberId(String memberId) {
