160	
161	    public LocalDate getRegistrationDate() {
162	        return this.registrationDate;
163	    }
164	
165	    public void setRegistrationDate(LocalDate registrationDate) {
166	        this.registrationDate = registrationDate;
167	    }
168	
169	    @PrePersist
170	    void defaultRegistrationDate() {
171	        if (this.registrationDate == null) {
172	            this.registrationDate = LocalDate.now();
173	        }
174	        this.registrationDate = BusinessDays.roll(this.registrationDate);
175	    }
176	
177	    public String getEmail() {
178	        return this.email;
179	    }
180	
181	    public void setEmail(String email) {
182	        this.email = email;
183	    }
184	
185	    public String getAddress() {
186	        return this.address;
187	    }
188	
189	    public void setAddress(String address) {
190	        this.address = address;
191	    }
192	
193	    public String getCity() {
194	        return this.city;
195	    }
196	
197	    public void setCity(String city) {
198	        this.city = city;
199	    }
200	
201	    public String getTelephone() {
202	        return this.telephone;
203	    }
204	
205	    public void setTelephone(String telephone) {
206	        this.telephone = telephone;
207	    }
208	
209	    protected Set<Pet> getPetsInternal() {
210	        if (this.pets == null) {
211	            this.pets = new HashSet<>();
212	        }
213	        return this.pets;
214	    }
215	
216	    protected void setPetsInternal(Set<Pet> pets) {
217	        this.pets = pets;
218	    }
219	
220	    public List<Pet> getPets() {
221	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
222	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
223	        return Collections.unmodifiableList(sortedPets);
224	    }
225	
226	    public void setPets(List<Pet> pets) {
227	        this.pets = new HashSet<>(pets);
228	    }
229	
230	    public void addPet(Pet pet) {
231	        getPetsInternal().add(pet);
232	        pet.setOwner(this);
233	    }
234	
235	    /**
236	     * Return the Pet with the given name, or null if none found for this Owner.
237	     *
238	     * @param name to test
239	     * @return true if pet name is already in use
240	     */
241	    public Pet getPet(String name) {
242	        return getPet(name, false);
243	    }
244	
245	    /**
246	     * Return the Pet with the given name, or null if none found for this Owner.
247	     *
248	     * @param name to test
249	     * @return true if pet name is already in use
250	     */
251	    public Pet getPet(String name, boolean ignoreNew) {
252	        name = name.toLowerCase();
253	        for (Pet pet : getPetsInternal()) {
254	            if (!ignoreNew || !pet.isNew()) {
255	                String compName = pet.getName();
256	                compName = compName.toLowerCase();
257	                if (compName.equals(name)) {
258	                    return pet;
259	                }
260	            }
261	        }
262	        return null;
263	    }
264	
265	    public Pet getPet(Integer petId) {
266	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
267	    }
268	
269	    @Override
270	    public String toString() {
271	        return new ToStringCreator(this)
272	
273	            .append("id", this.getId())
274	            .append("new", this.isNew())
275	            .append("lastName", this.getLastName())
276	            .append("firstName", this.getFirstName())
277	            .append("address", this.address)
278	            .append("city", this.city)
279	            .append("telephone", this.telephone)
280	            .toString();
281	    }
282	}
