3	import java.util.concurrent.atomic.AtomicLong;
4	
5	import org.slf4j.Logger;
6	import org.slf4j.LoggerFactory;
7	
8	import jakarta.persistence.PostPersist;
9	
10	/**
11	 * Emits an audit trail entry via the dedicated {@code AUDIT} logger whenever a new
12	 * owner is persisted, carrying the owner id, customer code and registration date.
13	 */
14	public class OwnerAuditListener {
15	
16	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
17	
18	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
19	
20	    private static final AtomicLong SEQ = new AtomicLong();
21	
22	    @PostPersist
23	    void onCreate(Owner owner) {
24	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
25	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
26	            org.springframework.samples.petclinic.rest.controller.v1.MembershipLevel.of(owner));
27	        AUDIT.info(String.format(
28	            "{\"schemaVersion\":2,\"seq\":%d,\"ownerId\":%d,\"memberId\":\"%s\",\"membershipLevel\":%d,"
29	                + "\"ownerSegment\":\"%s\",\"event\":\"OWNER_CREATED\"}",
30	            SEQ.incrementAndGet(), owner.getId(), owner.getMemberId(),
31	            org.springframework.samples.petclinic.rest.controller.v1.MembershipLevel.of(owner),
32	            org.springframework.samples.petclinic.rest.controller.v1.OwnerSegment.of(owner)));
33	        NOTIFY.info("welcome owner id={} memberId={}", owner.getId(), owner.getMemberId());
34	    }
35	}
