28	/**
29	 * Rejects an {@link OwnerFieldsDto} whose required identity fields are missing or blank
30	 * (null, empty or whitespace-only). This complements the schema's bean-validation
31	 * constraints, which do not treat a whitespace-only address or city as invalid.
32	 */
33	public class OwnerFieldsValidator implements Validator {
34	
35	    private static final List<String> REQUIRED_FIELDS =
36	        List.of("firstName", "lastName", "address", "city", "telephone");
37	
38	    @Override
39	    public boolean supports(Class<?> clazz) {
40	        return OwnerFieldsDto.class.isAssignableFrom(clazz);
41	    }
42	
43	    @Override
44	    public void validate(Object target, Errors errors) {
45	        OwnerFieldsDto owner = (OwnerFieldsDto) target;
46	        owner.setAddress(composeAddress(owner));
47	        for (String field : REQUIRED_FIELDS) {
48	            ValidationUtils.rejectIfEmptyOrWhitespace(errors, field, "required", "must not be blank");
49	        }
50	        String telephone = owner.getTelephone();
51	        String raw = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
52	        String e164 = raw.startsWith("+") ? raw
53	            : "+61" + (raw.startsWith("0") ? raw.substring(1) : raw);
54	        if (E164Telephone.isValid(e164)) {
55	            owner.setTelephone(e164);
56	        } else {
57	            errors.rejectValue("telephone", "telephone", "must be a valid E.164 telephone number");
58	        }
59	        String email = owner.getEmail();
60	        if (email != null) {
61	            owner.setEmail(email.toLowerCase(Locale.ROOT));
62	        }
63	        DisposableEmailDomains.reject(owner.getEmail(), errors);
64	        validatePostcode(owner, errors);
65	        validateRegistrationDate(owner, errors);
66	    }
67	
68	    /** The effective, normalized address: the composed structured lines when a non-blank
69	     * addressLine1 is supplied (addressLine2 appended after a single space when present),
70	     * otherwise the normalized flat address for backward compatibility. */
71	    private String composeAddress(OwnerFieldsDto owner) {
72	        String line1 = AddressNormalizer.normalize(owner.getAddressLine1());
73	        if (line1.isEmpty()) {
74	            return AddressNormalizer.normalize(owner.getAddress());
75	        }
76	        String line2 = AddressNormalizer.normalize(owner.getAddressLine2());
77	        return line2.isEmpty() ? line1 : line1 + " " + line2;
78	    }
79	
80	    /** Rejects a supplied registrationDate later than the current server date. */
81	    private void validateRegistrationDate(OwnerFieldsDto owner, Errors errors) {
82	        LocalDate registrationDate = owner.getRegistrationDate();
83	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
84	            errors.rejectValue("registrationDate", "registrationDate", "must not be in the future");
85	        }
86	    }
87	
88	    /** Rejects a supplied 4-digit postcode that falls outside the range for the city's
89	     * region. Absent postcodes and cities with no known region are accepted. */
90	    private void validatePostcode(OwnerFieldsDto owner, Errors errors) {
91	        String postcode = owner.getPostcode();
92	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
93	            return;
94	        }
95	        int[] range = switch (owner.getCity() == null ? "" : owner.getCity()) {
96	            case "Sydney" -> new int[] {2000, 2099};
97	            case "Melbourne" -> new int[] {3000, 3099};
98	            case "Brisbane" -> new int[] {4000, 4099};
99	            default -> null;
100	        };
101	        int value = Integer.parseInt(postcode);
102	        if (range != null && (value < range[0] || value > range[1])) {
103	            errors.rejectValue("postcode", "postcode", "must be valid for the city's region");
104	        }
105	    }
106	}
