2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.util.Collection;
6	
7	import org.springframework.samples.petclinic.model.Owner;
8	
9	/**
10	 * Single source of duplicate detection: an owner's identity is the SHA-256 hex of
11	 * {@code normalizedTelephone|lowerEmail|soundex(lastName)} (email empty when absent). Two owners
12	 * collide only when their whole keys are equal, so members of one household (same last name and
13	 * postcode) with different telephones stay distinct and surface only as soft matches.
14	 */
15	public final class IdentityKey {
16	
17	    private IdentityKey() {
18	    }
19	
20	    /** The derived identity key of {@code owner}; telephone is already E.164-normalized upstream. */
21	    public static String of(Owner owner) {
22	        String raw = "V2|" + blank(owner.getTelephone()) + "|" + lower(owner.getEmail()) + "|"
23	            + Soundex.code(owner.getLastName());
24	        try {
25	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(raw.getBytes(StandardCharsets.UTF_8));
26	            StringBuilder sb = new StringBuilder(digest.length * 2);
27	            for (byte b : digest) {
28	                sb.append(String.format("%02x", b));
29	            }
30	            return sb.toString();
31	        }
32	        catch (Exception e) {
33	            throw new IllegalStateException(e);
34	        }
35	    }
36	
37	    /** {@code true} when an existing owner has the exact same identity key as {@code candidate}. */
38	    static boolean isDuplicate(Owner candidate, Collection<Owner> existing) {
39	        String key = of(candidate);
40	        return existing.stream().anyMatch(other -> of(other).equals(key));
41	    }
42	
43	    private static String blank(String value) {
44	        return value == null ? "" : value;
45	    }
46	
47	    private static String lower(String value) {
48	        return value == null ? "" : value.toLowerCase();
49	    }
50	}
