2	
3	import java.util.Collection;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Soft duplicate detection. A candidate that is not a hard {@link IdentityKey} duplicate but whose
9	 * last name (by {@link Soundex}) and postcode match an existing owner's is a possible duplicate of
10	 * that owner. A declared household member ({@code sharesHousehold}) is not a suspected duplicate.
11	 */
12	final class PossibleDuplicates {
13	
14	    private PossibleDuplicates() {
15	    }
16	
17	    /** Id of the earliest existing owner {@code candidate} softly duplicates, or {@code null} when none. */
18	    static Integer matchId(Owner candidate, Collection<Owner> existing, Boolean sharesHousehold) {
19	        if (Boolean.TRUE.equals(sharesHousehold)) {
20	            return null;
21	        }
22	        String key = IdentityKey.of(candidate);
23	        String soundex = Soundex.code(candidate.getLastName());
24	        String postcode = candidate.getPostcode();
25	        return existing.stream()
26	            .filter(other -> !IdentityKey.of(other).equals(key))
27	            .filter(other -> soundex.equals(Soundex.code(other.getLastName())))
28	            .filter(other -> postcode != null && postcode.equals(other.getPostcode()))
29	            .map(Owner::getId)
30	            .filter(other -> other != null)
31	            .min(Integer::compareTo)
32	            .orElse(null);
33	    }
34	}
