12	
13	    private Namesakes() {
14	    }
15	
16	    /** Number of {@code existing} owners sharing {@code candidate}'s firstName and lastName. */
17	    static int count(Owner candidate, Collection<Owner> existing) {
18	        return (int) existing.stream()
