2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.time.LocalDate;
6	import java.util.Collection;
7	import java.util.HashSet;
8	import java.util.Set;
9	
10	import org.springframework.samples.petclinic.model.BusinessDays;
11	import org.springframework.samples.petclinic.model.Owner;
12	
13	/**
14	 * Builds an owner's memberId in the form {@code <REGION><FY><HASH8><CHK>}: the region derived
15	 * from the postcode, the 2-digit fiscal year, the first 8 upper-case hex characters of SHA-256
16	 * over the owner's normalized telephone and last name, and a single Luhn check digit over them.
17	 */
18	public final class CustomerCodes {
19	
20	    private CustomerCodes() {
21	    }
22	
23	    /** The {@code <REGION><FY><HASH8><CHK>} memberId for {@code owner}. */
24	    static String build(Owner owner, Collection<Owner> existing) {
25	        LocalDate registration = BusinessDays.roll(
26	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now());
27	        String base = regionV2(owner)
28	            + String.format("%02d", FiscalYear.of(registration) % 100)
29	            + hash8(owner.getTelephone() + owner.getLastName());
30	        return deduplicate(base + CheckDigit.luhn(base), existing);
31	    }
32	
33	    /** {@code code}, or the first {@code code-<n>} (n starting at 2) not held by an owner in {@code existing}. */
34	    private static String deduplicate(String code, Collection<Owner> existing) {
35	        Set<String> used = new HashSet<>();
36	        for (Owner owner : existing) {
37	            used.add(owner.getMemberId());
38	        }
39	        String candidate = code;
40	        for (int n = 2; used.contains(candidate); n++) {
41	            candidate = code + "-" + n;
42	        }
43	        return candidate;
44	    }
45	
46	    /**
47	     * The version-2 region code used inside identifiers: the plain {@link #region} with the fixed
48	     * {@code V2} version tag mixed in, so version-2 identifiers never repeat a version-1 value while
49	     * the user-facing locality keeps the plain region code.
50	     */
51	    static String regionV2(Owner owner) {
52	        return region(owner) + "V2";
53	    }
54	
55	    /** The region code derived from {@code owner}'s postcode, falling back to its city, else {@code UNKNOWN}. */
56	    public static String region(Owner owner) {
57	        String prefix = owner.getPostcode() != null && owner.getPostcode().matches("[0-9]{4}")
58	            ? owner.getPostcode().substring(0, 2) : "";
59	        return switch (prefix) {
60	            case "20" -> "NSW";
61	            case "30" -> "VIC";
62	            case "40" -> "QLD";
63	            default -> switch (owner.getCity() == null ? "" : owner.getCity()) {
64	                case "Sydney" -> "NSW";
65	                case "Melbourne" -> "VIC";
66	                case "Brisbane" -> "QLD";
67	                default -> "UNKNOWN";
68	            };
69	        };
70	    }
71	
72	    /** The first 8 upper-case hex characters of SHA-256 over {@code value}. */
73	    private static String hash8(String value) {
74	        try {
75	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
76	            StringBuilder sb = new StringBuilder();
77	            for (int i = 0; i < 4; i++) {
78	                sb.append(String.format("%02X", digest[i]));
79	            }
80	            return sb.toString();
81	        }
82	        catch (Exception e) {
83	            throw new IllegalStateException(e);
84	        }
85	    }
86	}
