4	import java.util.OptionalInt;
5	
6	import org.springframework.samples.petclinic.model.Owner;
7	
8	/**
9	 * Caps a new owner's membership level relative to their household. A new owner's level cannot
10	 * exceed one above the current maximum {@link MembershipLevel} among their existing household
11	 * members; with no existing household member no cap applies.
12	 */
13	public final class MembershipCap {
14	
15	    private MembershipCap() {
16	    }
17	
18	    /**
19	     * The level ceiling for {@code candidate}: one above the highest {@link MembershipLevel} among
20	     * {@code existing} owners sharing its household, or {@code null} when it has no household peer.
21	     */
22	    public static Integer of(Owner candidate, Collection<Owner> existing) {
23	        OptionalInt max = existing.stream()
24	            .filter(o -> !o.isDeleted())
25	            .filter(o -> candidate.getHouseholdId() != null
26	                && candidate.getHouseholdId().equals(o.getHouseholdId()))
27	            .mapToInt(MembershipLevel::of)
28	            .max();
29	        return max.isPresent() ? max.getAsInt() + 1 : null;
30	    }
31	
32	    /** The owner's {@link MembershipLevel} limited to its stored {@link Owner#getMembershipCap()}. */
33	    public static int level(Owner owner) {
34	        int level = MembershipLevel.of(owner);
35	        Integer cap = owner.getMembershipCap();
36	        return cap == null ? level : Math.min(level, cap);
37	    }
38	}
