3	import java.time.DayOfWeek;
4	import java.time.LocalDate;
5	import java.util.Set;
6	
7	/**
8	 * Business-day helper: a registration date must fall on a business day, so a
9	 * Saturday, Sunday, or public holiday is rolled forward to the next business day.
10	 */
11	public final class BusinessDays {
12	
13	    private static final Set<LocalDate> HOLIDAYS = Set.of(
14	        LocalDate.of(2026, 1, 1),
15	        LocalDate.of(2026, 1, 26),
16	        LocalDate.of(2026, 4, 25),
17	        LocalDate.of(2026, 12, 25),
18	        LocalDate.of(2026, 12, 28));
19	
20	    private BusinessDays() {
21	    }
22	
23	    private static boolean isBusinessDay(LocalDate date) {
24	        return date.getDayOfWeek() != DayOfWeek.SATURDAY && date.getDayOfWeek() != DayOfWeek.SUNDAY
25	            && !HOLIDAYS.contains(date);
26	    }
27	
28	    /**
29	     * Returns {@code date} unchanged when it is a business day, or the next business
30	     * day when it falls on a weekend or a public holiday.
31	     */
32	    public static LocalDate roll(LocalDate date) {
33	        while (!isBusinessDay(date)) {
34	            date = date.plusDays(1);
35	        }
36	        return date;
37	    }
38	}
