3	import java.time.LocalDate;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Derives an owner's membership standing from a points score. Points start at 0 and gain
9	 * 2 for a present email, 1 when namesakeCount is 0, 2 for a household of 3 or more, and 3
10	 * for a tenure of one or more elapsed fiscal years measured from the registration date. The score maps to
11	 * a level of 1 (0-1 points), 2 (2-3), 3 (4-5) or 4 (6 or more).
12	 */
13	public final class MembershipLevel {
14	
15	    private MembershipLevel() {
16	    }
17	
18	    /** The membership points of {@code owner}. */
19	    public static int points(Owner owner) {
20	        return (owner.getEmail() != null ? 2 : 0)
21	            + (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0 ? 1 : 0)
22	            + (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3 ? 2 : 0)
23	            + (FiscalYear.tenure(owner, LocalDate.now()) >= 1 ? 3 : 0);
24	    }
25	
26	    /** The membership level of {@code owner} (1-4), mapped from its {@link #points(Owner)}. */
27	    public static int of(Owner owner) {
28	        return Math.min(4, points(owner) / 2 + 1);
29	    }
30	}
