3	/**
4	 * American Soundex phonetic code of a surname: the first letter followed by up to three digits.
5	 * Used by identity and soft-duplicate detection so that similar-sounding last names group together.
6	 */
7	final class Soundex {
8	
9	    /** Digit for each letter A..Z ('0' = not coded). Indexed by {@code letter - 'A'}. */
10	    private static final String MAP = "01230120022455012623010202";
11	
12	    private Soundex() {
13	    }
14	
15	    /** American Soundex code (letter + three digits) of {@code name}; {@code "0000"} when blank. */
16	    static String code(String name) {
17	        String s = name == null ? "" : name.toUpperCase().replaceAll("[^A-Z]", "");
18	        if (s.isEmpty()) {
19	            return "0000";
20	        }
21	        StringBuilder sb = new StringBuilder().append(s.charAt(0));
22	        char prev = MAP.charAt(s.charAt(0) - 'A');
23	        for (int i = 1; i < s.length() && sb.length() < 4; i++) {
24	            char c = s.charAt(i);
25	            char d = MAP.charAt(c - 'A');
26	            if (d != '0' && d != prev) {
27	                sb.append(d);
28	            }
29	            if (c != 'H' && c != 'W') {
30	                prev = d;
31	            }
32	        }
33	        while (sb.length() < 4) {
34	            sb.append('0');
35	        }
36	        return sb.toString();
37	    }
38	}
