3	/**
4	 * The single Luhn check digit (0-9) over the digits of a string, used as the CHK segment
5	 * of a memberId so it can be validated without recomputing how it was built.
6	 */
7	public final class CheckDigit {
8	
9	    private CheckDigit() {
10	    }
11	
12	    /** The Luhn check digit (0-9) over the digits contained in {@code value}. */
13	    static int luhn(String value) {
14	        int sum = 0;
15	        boolean dbl = true;
16	        for (int i = value.length() - 1; i >= 0; i--) {
17	            int d = value.charAt(i) - '0';
18	            if (d < 0 || d > 9) {
19	                continue;
20	            }
21	            if (dbl && (d *= 2) > 9) {
22	                d -= 9;
23	            }
24	            sum += d;
25	            dbl = !dbl;
26	        }
27	        return (10 - (sum % 10)) % 10;
28	    }
29	}
